try{const setup=await api('/api/setup');if(setup.needed){$('loginForm').hidden=true;$('setupForm').hidden=false;$('demoHelp').hidden=true;}else{try{const session=await api('/api/session');if(sessionStorage.getItem('litaliano-session-closed')){csrf=session.csrf;await api('/api/logout',{});csrf='';}else{csrf=session.csrf;section=session.user.role==='caja'?'cash':session.user.role==='cocina'?'kitchen':'service';connected();}}catch{}}}catch(e){$('loginError').textContent='No se pudo conectar al servidor. Inicia la app para continuar.';}

function reservationBoard(){
 const rows=(state.reservations||[]).slice().sort((a,b)=>(a.date+a.time).localeCompare(b.date+b.time));
 return '<p>Confirma disponibilidad con el cliente antes de asignar una mesa. La solicitud no confirma una reserva automáticamente.</p><p class="help">Horario de Antofagasta. Margen de planificación por mesa: 90 minutos. Verifica personalmente capacidad y horario de atención.</p>'+['requested','confirmed','arrived','cancelled','no_show'].map(status=>'<section class="panel"><h2>'+esc({requested:'Por confirmar',confirmed:'Confirmadas',arrived:'Llegadas registradas',cancelled:'Anuladas',no_show:'Sin asistencia'}[status])+'</h2><div class="cards">'+(rows.filter(r=>r.status===status).map(r=>'<article class="card"><div class="card-head"><h3>'+esc(r.name)+'</h3><span class="pill">'+esc(r.code)+'</span></div><p>'+esc(r.date)+' · '+esc(r.time)+' · '+r.guests+' personas'+(r.table?' · Mesa '+r.table:'')+'</p><p>Teléfono: '+esc(r.phone)+'</p><p>Correo: '+esc(r.email||'No indicado')+'</p>'+(r.emailDelivery?'<p>'+esc({sending:'Correo en proceso',accepted:'Correo aceptado por el servidor del hosting',failed:'Envío fallido · revisa la configuración antes de reintentar',unknown:'Resultado pendiente de revisión en el hosting'}[r.emailDelivery.status])+'</p>':'')+(r.notes?'<p class="notes">'+esc(r.notes)+'</p>':'')+(r.cancelReason?'<p>Motivo: '+esc(r.cancelReason)+'</p>':'')+'<div class="actions">'+(status==='requested'?button('reservationConfirm',r.id,'Revisar y confirmar'):'')+(status==='confirmed'?button('reservationEmail',r.id,'Confirmar por correo','primary')+button('reservationArrive',r.id,'Registrar llegada','good')+button('reservationNoShow',r.id,'Registrar ausencia','quiet'):'')+(['requested','confirmed'].includes(status)?button('reservationCancel',r.id,'Anular solicitud','danger'):'')+'</div></article>').join('')||'<p>Sin reservas en este estado.</p>')+'</div></section>').join('');
}
async function reservationDialog(action,key){
 const r=state.reservations.find(r=>r.id===key);if(!r)return;
 if(action==='reservationConfirm')modal('Confirmar reserva · '+r.code,'<p>'+esc(r.name)+' · '+esc(r.date)+' · '+esc(r.time)+' · '+r.guests+' personas</p><p>Teléfono: '+esc(r.phone)+'</p><p>Confirma con el cliente el horario y la capacidad de la mesa. Después de confirmar puedes abrir la opción Confirmar por correo.</p><form data-form="reservation" data-id="'+key+'"><input type="hidden" name="action" value="confirm"><label>Mesa<select name="table" required><option value="">Seleccionar mesa</option>'+Array.from({length:state.settings.tableCount},(_,i)=>'<option value="'+(i+1)+'">Mesa '+(i+1)+'</option>').join('')+'</select></label><button class="primary">Confirmar reserva</button></form>');
 if(action==='reservationEmail'){const preview=await api('/api/reservation/email?id='+encodeURIComponent(key));modal('Confirmación por correo · '+r.code,'<p>Revisa el destinatario y el mensaje antes de enviar.</p>'+(!preview.configured?'<p class="notes">El correo del hosting está pendiente de configurar. Puedes revisar el diseño; el envío está deshabilitado.</p>':'<p>Remitente: '+esc(preview.sender)+'</p>')+'<iframe title="Vista previa del correo de confirmación" sandbox="" srcdoc="'+esc(preview.html)+'" style="width:100%;height:440px;border:1px solid #ddd0be;border-radius:8px;background:#f4eee5"></iframe><form data-form="reservationEmail" data-id="'+key+'"><label>Correo del cliente<input type="email" name="email" value="'+esc(r.email||'')+'" required maxlength="254"></label><p class="help">La aceptación por el servidor SMTP no garantiza la llegada a la bandeja del cliente. No se reenvía automáticamente.</p><button class="primary" '+(!preview.configured||['sending','accepted','unknown'].includes(r.emailDelivery?.status)?'disabled':'')+'>Enviar confirmación por correo</button></form>');}
 if(action==='reservationCancel')modal('Anular reserva · '+r.code,'<form data-form="reservation" data-id="'+key+'"><input type="hidden" name="action" value="cancel"><label>Motivo<textarea name="reason" required maxlength="400"></textarea></label><button class="danger">Confirmar anulación</button></form>');
 if(action==='reservationArrive'||action==='reservationNoShow')modal(action==='reservationArrive'?'Registrar llegada':'Registrar ausencia','<p>'+esc(r.name)+' · Mesa '+esc(r.table)+' · '+esc(r.date)+' '+esc(r.time)+'</p><p>'+(action==='reservationArrive'?'Se abrirá una atención de mesa asignada a tu usuario. La mesa debe estar disponible.':'Se marcará que el cliente no asistió. Solo se permite después de la hora confirmada.')+'</p><form data-form="reservation" data-id="'+key+'"><input type="hidden" name="action" value="'+(action==='reservationArrive'?'arrive':'no_show')+'"><button class="primary">Confirmar registro</button></form>');
}

function rewardsBoard(){const data=state.rewards,prizes=data.prizes;return '<p>Consulta el código del cupón y registra el canje en una atención de mesa. Un premio por cuenta y visita.</p>'+(state.demo?'<p class="notes">Campaña de demostración. Cantidades de ejemplo; estos cupones no activan una promoción real del restaurante.</p>':'')+'<div class="panel"><form data-form="rewardLookup"><label>Código del premio<input name="code" placeholder="SOR01-… o LIM02-…" required maxlength="40" autocomplete="off"></label><p class="help">Escribe o pega el código. Un lector QR puede introducirlo en este campo.</p><button class="primary">Verificar premio</button></form></div>'+'<div class="metrics">'+[[prizes.length,'Premios emitidos'],[prizes.filter(p=>p.status==='redeemed').length,'Canjeados'],[prizes.filter(p=>p.status==='issued').length,'Pendientes'],[prizes.filter(p=>p.status==='expired').length,'Vencidos']].map(([n,label])=>metric(n,label)).join('')+'</div>'+(can()?'<section class="panel"><h2>Control de campaña</h2><form data-form="rewardSettings"><label class="checkbox"><input name="enabled" type="checkbox" '+(data.campaign.enabled?'checked':'')+'> Emitir premios físicos</label><label>Vigencia de nuevos cupones · días<input name="days" type="number" min="1" max="90" value="'+data.campaign.days+'" required></label>'+Object.entries(data.types).map(([type,name])=>'<label>'+esc(name)+' · máximo total de cupones<input name="'+type+'" type="number" min="'+prizes.filter(p=>p.type===type).length+'" max="10000" value="'+data.campaign.limits[type]+'" required></label>').join('')+'<p class="help">El máximo incluye emitidos, canjeados y vencidos. No reduce los premios existentes. No son existencias de materias primas.</p><button class="primary">Guardar campaña</button></form><p><a class="export" href="/api/export/rewards">Exportar registro de premios ↓</a></p></section>':'')+'<section class="panel"><h2>Registro de premios</h2>'+table(['Código','Premio','Estado','Vence','Canje','Mesa','Usuario'],prizes.slice().reverse().map(p=>[esc(p.code),esc(p.label),esc({issued:'Disponible',redeemed:'Canjeado',expired:'Vencido'}[p.status]),date(p.expiresAt),date(p.redeemedAt),esc(p.table||'—'),esc(p.redeemedByName||'—')]))+'</section>';}
async function rewardLookup(code){const {prize:p}=await api('/api/rewards/lookup?code='+encodeURIComponent(code));modal('Verificar premio','<p><strong>'+esc(p.label)+'</strong></p><p>Código: '+esc(p.code)+'</p><p>Estado: '+esc({issued:'Disponible',redeemed:'Canjeado',expired:'Vencido'}[p.status])+'</p><p>Vence: '+date(p.expiresAt)+'</p>'+(p.demo?'<p class="notes">Cupón de demostración; no canje real.</p>':'')+(p.status==='issued'?'<form data-form="rewardRedeem"><input name="code" type="hidden" value="'+esc(p.code)+'"><label>Atención de mesa<select name="visitId" required><option value="">Seleccionar cuenta</option>'+state.visits.filter(v=>['open','payment_pending'].includes(v.status)).map(v=>'<option value="'+esc(v.id)+'">Mesa '+esc(v.table)+' · '+esc(userName(v.waiterId))+'</option>').join('')+'</select></label><p class="help">Confirmar registra la entrega del premio y bloquea nuevos usos del código. No modifica precios ni descuenta ingredientes.</p><button class="primary">Confirmar canje'+(p.demo?' de prueba':'')+'</button></form>':'<p>Este premio no admite otro canje.</p>'));}

function openInventoryImport(){
 modal('Importar inventario','<p>Usa las columnas de la plantilla. La existencia indicada reemplaza el saldo contado; no se suma al inventario.</p><p><a href="/api/inventory/template">Plantilla Excel vacía ↓</a> · <a href="/api/inventory/template?format=csv">Plantilla CSV ↓</a> · <a href="/api/inventory/template?current=1">Excel con inventario actual ↓</a></p><form data-form="inventoryPreview"><label>Archivo Excel o CSV<input type="file" name="inventoryFile" accept=".xlsx,.csv" required></label><label>Qué deseas cargar<select name="mode"><option value="create">Crear materias primas nuevas</option><option value="update">Actualizar materias primas existentes</option><option value="merge">Crear y actualizar</option></select></label><p class="help">Máximo 2 MB / 1.000 filas. Unidad: g, ml o unidad. Costo en CLP por unidad base. CSV UTF-8, coma o punto y coma; decimales con coma o punto, sin miles. No se aceptan fórmulas. Identifica con el código al actualizar.</p><button class="primary">Revisar archivo</button></form>');
}
async function submitInventoryImport(form){
 const submit=form.querySelector('button');submit.disabled=true;try{
  if(form.dataset.form==='inventoryPreview'){
   const file=form.inventoryFile.files[0];if(!file||file.size>2*1024*1024)throw Error('Selecciona un archivo de hasta 2 MB.');
   const data=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onerror=()=>reject(Error('No se pudo leer el archivo.'));reader.onload=()=>resolve(String(reader.result).split(',')[1]);reader.readAsDataURL(file);});
   const preview=await api('/api/inventory/import/preview',{filename:file.name,base64:data,mode:form.mode.value});
   modal('Revisar importación · '+file.name,'<p>'+preview.created+' por crear · '+preview.updated+' por actualizar. Los saldos se reemplazan por los valores del archivo.</p><div style="max-height:45vh;overflow:auto">'+table(['Fila','Acción','Materia prima','Unidad','Existencia actual → nueva','Mínimo','Costo CLP/base','Resultado'],preview.rows.map(r=>[r.row,r.action==='create'?'Crear':'Actualizar',esc(r.name),esc(r.unit),esc((r.previous?.stock??'—')+' → '+r.stock),r.minimum,r.unitCost,r.errors.length?'<span class="error">'+r.errors.map(esc).join('<br>')+'</span>':'Correcto']))+'</div>'+(preview.valid?'<form data-form="inventoryApply" data-token="'+esc(preview.token)+'"><label>Motivo de carga<textarea name="reason" maxlength="400" placeholder="Conteo físico, recepción de compra…" required></textarea></label><label class="checkbox"><input type="checkbox" name="confirm" required> Revisé los cambios y confirmo reemplazar los saldos de estas materias primas.</label><button class="primary">Confirmar e importar '+preview.rows.length+' materias primas</button></form>':'<p class="error">No se aplicó ningún cambio. Corrige todas las filas indicadas y vuelve a revisar el archivo.</p>')+'<button type="button" data-action="importInventory" class="quiet">Elegir otro archivo</button>');
  }else{await mutation('/api/inventory/import/apply',{token:form.dataset.token,reason:form.reason.value,confirm:form.confirm.checked},'Inventario importado correctamente');$('modal').close();}
 }catch(e){$('modalError').textContent=e.message;}finally{submit.disabled=false;}
}
